            testStateNode.textContent = tp('admin_ai.status_prefix', 'Status: ') + status + ' • ' + tp('admin_ai.latency_prefix', 'Latency: ') + latency + ' • ' + tp('admin_ai.model_cap_prefix', 'Model: ') + model
