    var intentsBody = document.getElementById('adminAiIntentsBody');
    if (intentsBody) {
      if (!intentSettings.length) {
        intentsBody.innerHTML = '<tr><td colspan="6" class="text-muted">' + safeText(tp('admin_ai.intents_empty', 'No intents are configured yet.')) + '</td></tr>';
      } else {
        var providerByPublicId = {};
        providers.forEach(function (item) {
          var id = String(item && item.public_id ? item.public_id : '').trim();
          if (!id) return;
          providerByPublicId[id] = item;
        });
        var defaultActiveProvider = providers.find(function (item) {
          return Boolean(item && item.is_default && item.is_active);
        }) || providers.find(function (item) {
          return Boolean(item && item.is_active);
        }) || null;
        var defaultActiveProviderId = defaultActiveProvider ? String(defaultActiveProvider.public_id || '').trim() : '';

        var activePromptByIntent = {};
        promptTemplates.forEach(function (item) {
          if (!item || !item.is_active) return;
          var code = String(item.intent_code || '').trim();
          if (!code) return;
          if (activePromptByIntent[code]) return;
          var locale = String(item.locale || '').trim() || 'ru-ru';
          var version = String(item.version || '1').trim();
          activePromptByIntent[code] = locale + ' v' + version;
        });

        var activeSchemaByIntent = {};
        jsonSchemas.forEach(function (item) {
          if (!item || !item.is_active) return;
          var code = String(item.intent_code || '').trim();
          if (!code) return;
          if (activeSchemaByIntent[code]) return;
          var version = String(item.schema_version || 'v1').trim();
          activeSchemaByIntent[code] = version;
        });

        var retentionSummary = retentionItems.map(function (item) {
          var code = String(item.policy_code || '').trim();
          var days = Number(item.retention_days || 0);
          if (!code) return '';
          return code + ':' + String(days > 0 ? days : 30) + 'd';
        }).filter(Boolean).slice(0, 3).join(', ');

        function detectIntentDomain(intentCode) {
          var code = String(intentCode || '').toLowerCase();
          if (code.indexOf('dashboard') === 0) return 'dashboard';
          if (code.indexOf('task') === 0 || code.indexOf('checklist') >= 0) return 'tasks';
          if (code.indexOf('project') === 0) return 'projects';
          if (code.indexOf('client') === 0 || code.indexOf('company') === 0 || code.indexOf('contact') === 0) return 'clients';
          if (code.indexOf('calendar') === 0 || code.indexOf('my_day') === 0 || code.indexOf('my-day') === 0) return 'calendar';
          if (code.indexOf('analytics') === 0 || code.indexOf('risk') >= 0 || code.indexOf('digest') >= 0) return 'analytics';
          if (code.indexOf('cron') >= 0 || code.indexOf('daily_') === 0) return 'cron';
          if (code.indexOf('search') >= 0 || code.indexOf('semantic') >= 0) return 'search';
          if (code.indexOf('admin') === 0) return 'admin';
          return 'other';
        }

        var domainLabels = {
          dashboard: 'Dashboard',
          tasks: 'Tasks',
          projects: 'Projects',
          clients: 'Clients',
          calendar: 'Calendar',
          analytics: 'Analytics',
          admin: 'Admin',
          cron: 'Cron',
          search: 'Search',
          other: 'Other'
        };
        var domainOrder = ['dashboard', 'tasks', 'projects', 'clients', 'calendar', 'analytics', 'admin', 'cron', 'search', 'other'];
        var groupedIntents = {};
        intentSettings.forEach(function (item) {
          var domain = detectIntentDomain(item && item.intent_code ? item.intent_code : '');
          if (!groupedIntents[domain]) groupedIntents[domain] = [];
          groupedIntents[domain].push(item);
        });

        var groupedRows = [];
        domainOrder.forEach(function (domain) {
          var items = groupedIntents[domain] || [];
          if (!items.length) return;
          groupedRows.push('<tr class="table-light"><td colspan="6"><strong>' + safeText(domainLabels[domain] || domain) + '</strong></td></tr>');
          items.forEach(function (item) {
            var intentCode = String(item.intent_code || '').trim();
            var featureFlag = String(item.feature_flag || '').trim();
            var model = String(item.model || '').trim();
            var intentProviderPublicId = String(item.provider_public_id || '').trim();
            var effectiveProviderPublicId = intentProviderPublicId || defaultActiveProviderId;
            var effectiveProvider = effectiveProviderPublicId ? (providerByPublicId[effectiveProviderPublicId] || null) : null;
            var providerTitle = effectiveProvider
              ? String(effectiveProvider.title || effectiveProvider.provider_code || effectiveProviderPublicId)
              : (effectiveProviderPublicId || tp('admin_ai.not_selected', 'not selected'));
            var requiredPermission = String(item.required_permission || '').trim();
            var maxTokens = Number(item.max_tokens || 0);
            var isEnabled = item.is_enabled ? '1' : '0';
            var sensitive = item.allow_sensitive_context ? '1' : '0';
            var requiresSensitivePermission = requiredPermission === 'ai.use_sensitive_context';
            var permissionMeta = safeText(requiredPermission || 'ai.use');
            var lastLog = intentLastLogByIntent[intentCode] || null;
            var lastMeta = tp('admin_ai.last_no_data', 'last: no data');
            if (lastLog) {
              var statusLabel = lastLog.is_error
                ? ('error' + (lastLog.error_code ? (' (' + lastLog.error_code + ')') : ''))
                : 'success';
              lastMeta = tp('admin_ai.last_prefix', 'last: ') + statusLabel + ' • ' + formatDate(lastLog.created_at || '');
            }
            if (requiresSensitivePermission) {
              permissionMeta += ' <span class="crm-chip">requires ai.use_sensitive_context</span>';
            }
            permissionMeta += '<div class="small text-muted">' + safeText(lastMeta) + '</div>';

            var promptLabel = activePromptByIntent[intentCode] || tp('admin_ai.not_set_m', 'not set');
            var schemaLabel = activeSchemaByIntent[intentCode] || tp('admin_ai.not_set_f', 'not set');
            var policiesMeta = 'masking: ' + (sensitive === '1' ? 'sensitive ON' : 'default')
              + (retentionSummary ? ('; retention: ' + retentionSummary) : '');

            groupedRows.push('<tr>'
              + '<td><strong>' + safeText(intentCode || '—') + '</strong><div class="small text-muted">' + permissionMeta + '</div></td>'
              + '<td><div class="small"><strong>' + safeText(providerTitle) + '</strong></div><div class="small text-muted">provider_public_id: ' + safeText(effectiveProviderPublicId || '—') + '</div>'
                + '<div class="mt-1"><input class="form-control form-control-sm" data-ai-intent-model="' + safeText(intentCode) + '" value="' + safeText(model || '') + '" maxlength="190" placeholder="gpt-4.1-mini"></div>'
              + '</td>'
              + '<td><div class="small">prompt: <span class="crm-chip">' + safeText(promptLabel) + '</span></div><div class="small mt-1">schema: <span class="crm-chip">' + safeText(schemaLabel) + '</span></div></td>'
              + '<td><input class="form-control form-control-sm" data-ai-intent-feature-flag="' + safeText(intentCode) + '" value="' + safeText(featureFlag || '') + '" maxlength="128" placeholder="ai.task"></td>'
              + '<td><div class="d-flex gap-2 align-items-center flex-wrap">'
                + '<input class="form-control form-control-sm" class="form-control form-control-sm crm-field-w-120" type="number" min="1" step="1" data-ai-intent-max-tokens="' + safeText(intentCode) + '" value="' + safeText(String(maxTokens > 0 ? maxTokens : 2000)) + '">'
                + '<select class="form-select form-select-sm" class="form-select form-select-sm crm-field-w-140" data-ai-intent-enabled="' + safeText(intentCode) + '"><option value="1"' + (isEnabled === '1' ? ' selected' : '') + '>' + safeText(tp('admin_ai.enabled', 'Enabled')) + '</option><option value="0"' + (isEnabled === '0' ? ' selected' : '') + '>' + safeText(tp('admin_ai.disabled', 'Disabled')) + '</option></select>'
                + '<select class="form-select form-select-sm" class="form-select form-select-sm crm-field-w-180" data-ai-intent-sensitive="' + safeText(intentCode) + '"><option value="0"' + (sensitive === '0' ? ' selected' : '') + '>' + safeText(tp('admin_ai.no_sensitive_data', 'No sensitive data')) + '</option><option value="1"' + (sensitive === '1' ? ' selected' : '') + '>' + safeText(tp('admin_ai.sensitive_data_allowed', 'Sensitive data allowed')) + '</option></select>'
                + '<div class="small text-muted w-100">' + safeText(policiesMeta) + '</div>'
              + '</div></td>'
              + '<td><button class="btn btn-sm btn-light" type="button" data-ai-intent-save="' + safeText(intentCode) + '">' + safeText(tp('common.save', 'Save')) + '</button></td>'
              + '</tr>');
          });
        });

        intentsBody.innerHTML = groupedRows.join('');
      }
    }

    var cronBody = document.getElementById('adminAiCronBody');
    var aiFlagsBody = document.getElementById('adminAiFlagsBody');
    var aiFeatureFlagCodes = [
      'ai.enabled',
      'ai.task',
      'ai.project',
      'ai.calendar',
      'ai.client',
      'ai.analytics',
      'ai.admin',
      'ai.search',
      'ai.workflow',
      'ai.import',
      'ai.cron.enabled',
      'ai.cron.daily_work_plan',
      'ai.cron.user_daily_digest',
      'ai.cron.user_weekly_plan',
      'ai.cron.manager_weekly_digest',
      'ai.cron.task_risk_scan',
      'ai.cron.task_quality_scan',
      'ai.cron.task_decomposition_scan',
      'ai.cron.meeting_agenda',
      'ai.cron.project_daily_summary',
      'ai.cron.client_weekly_report',
      'ai.cron.team_workload_scan',
      'ai.cron.sla_approval_scan',
      'ai.cron.data_quality_scan',
      'ai.cron.import_review',
      'ai.cron.security_log_review',
      'ai.cron.webhook_health_review',
      'ai.cron.workflow_audit',
      'ai.cron.semantic_index_refresh',
      'ai.cron.suggestion_cleanup'
    ];
    var featureFlagByCode = {};
    featureFlags.forEach(function (item) {
      var code = String(item && item.code ? item.code : '').trim();
      if (!code) return;
      featureFlagByCode[code] = item;
    });
    if (aiFlagsBody) {
      var aiFlagItems = aiFeatureFlagCodes.map(function (code) {
        return {
          code: code,
          item: featureFlagByCode[code] || null
        };
      });
      aiFlagsBody.innerHTML = aiFlagItems.map(function (entry) {
        var flag = entry.item;
        if (!flag) {
          return '<tr>'
            + '<td><strong>' + safeText(entry.code) + '</strong></td>'
            + '<td><span class="crm-badge archived">' + safeText(tp('admin_ai.not_found', 'not found')) + '</span></td>'
            + '<td><span class="text-muted small">—</span></td>'
            + '</tr>';
        }
        var publicId = String(flag.public_id || '').trim();
        var isEnabled = flag.is_enabled ? '1' : '0';
        return '<tr>'
          + '<td><strong>' + safeText(entry.code) + '</strong></td>'
          + '<td><select class="form-select form-select-sm" data-ai-flag-enabled="' + safeText(publicId) + '"><option value="1"' + (isEnabled === '1' ? ' selected' : '') + '>' + safeText(tp('admin_ai.enabled', 'Enabled')) + '</option><option value="0"' + (isEnabled === '0' ? ' selected' : '') + '>' + safeText(tp('admin_ai.disabled', 'Disabled')) + '</option></select></td>'
          + '<td><button class="btn btn-sm btn-light" type="button" data-ai-flag-save="' + safeText(publicId) + '">' + safeText(tp('common.save', 'Save')) + '</button></td>'
          + '</tr>';
      }).join('');
    }
    if (cronBody) {
      var cronItems = intentSettings.filter(function (item) {
        var intentCode = String(item.intent_code || '').toLowerCase();
        var featureFlag = String(item.feature_flag || '').toLowerCase();
        var requiredPermission = String(item.required_permission || '').toLowerCase();
        return intentCode.indexOf('cron') >= 0
          || featureFlag.indexOf('ai.cron') === 0
          || requiredPermission === 'ai.manage_cron_jobs'
          || requiredPermission === 'ai.view_cron_results';
      });

      if (!cronItems.length) {
        cronBody.innerHTML = '<tr><td colspan="5" class="text-muted">' + safeText(tp('admin_ai.cron_empty', 'No background intents found.')) + '</td></tr>';
      } else {
        cronBody.innerHTML = cronItems.map(function (item) {
          var intentCode = String(item.intent_code || '').trim();
          var featureFlag = String(item.feature_flag || '').trim();
          var model = String(item.model || '').trim();
          var isEnabled = item.is_enabled ? '1' : '0';
          return '<tr>'
            + '<td><strong>' + safeText(intentCode || '—') + '</strong></td>'
            + '<td><span class="crm-chip">' + safeText(featureFlag || 'ai.cron.*') + '</span></td>'
            + '<td>' + safeText(model || 'default') + '</td>'
            + '<td><select class="form-select form-select-sm" data-ai-cron-enabled="' + safeText(intentCode) + '"><option value="1"' + (isEnabled === '1' ? ' selected' : '') + '>' + safeText(tp('admin_ai.enabled', 'Enabled')) + '</option><option value="0"' + (isEnabled === '0' ? ' selected' : '') + '>' + safeText(tp('admin_ai.disabled', 'Disabled')) + '</option></select></td>'
            + '<td><button class="btn btn-sm btn-light" type="button" data-ai-cron-save="' + safeText(intentCode) + '">' + safeText(tp('common.save', 'Save')) + '</button></td>'
            + '</tr>';
        }).join('');
      }
    }

    var cronReloadBtn = document.getElementById('adminAiCronReloadBtn');
    if (cronReloadBtn && cronReloadBtn.dataset.bound !== '1') {
      cronReloadBtn.addEventListener('click', function () {
        renderAdminAiPage();
      });
      cronReloadBtn.dataset.bound = '1';
    }

    if (cronBody && cronBody.dataset.bound !== '1') {
      cronBody.addEventListener('click', async function (event) {
        var saveBtn = event.target.closest('[data-ai-cron-save]');
        if (!saveBtn) return;

        var intentCode = String(saveBtn.getAttribute('data-ai-cron-save') || '').trim();
        if (!intentCode) return;
        var enabledSelect = cronBody.querySelector('[data-ai-cron-enabled="' + intentCode.replace(/"/g, '\\"') + '"]');
        var isEnabled = String((enabledSelect && enabledSelect.value) || '1') === '1';
        try {
          await request('api/v1/ai/intent-settings/' + encodeURIComponent(intentCode), {
            method: 'PATCH',
            headers: { 'X-Idempotency-Key': window.CRM.api.createIdempotencyKey('ai-cron-intent-update') },
            body: { is_enabled: isEnabled }
          });
          notify(tp('admin_ai.cron_updated', 'Background intent updated'));
          await renderAdminAiPage();
        } catch (error) {
          var envelopeError = error && error.envelope ? error.envelope : null;
          notify((envelopeError && envelopeError.message) || tp('admin_ai.cron_update_fail', 'Failed to update background intent'), 'error');
        }
      });
      cronBody.dataset.bound = '1';
    }

    var aiFlagsReloadBtn = document.getElementById('adminAiFlagsReloadBtn');
    if (aiFlagsReloadBtn && aiFlagsReloadBtn.dataset.bound !== '1') {
      aiFlagsReloadBtn.addEventListener('click', function () {
        renderAdminAiPage();
      });
      aiFlagsReloadBtn.dataset.bound = '1';
    }

    if (aiFlagsBody && aiFlagsBody.dataset.bound !== '1') {
      aiFlagsBody.addEventListener('click', async function (event) {
        var saveBtn = event.target.closest('[data-ai-flag-save]');
        if (!saveBtn) return;
        var publicId = String(saveBtn.getAttribute('data-ai-flag-save') || '').trim();
        if (!publicId) return;
        var enabledSelect = aiFlagsBody.querySelector('[data-ai-flag-enabled="' + publicId.replace(/"/g, '\\"') + '"]');
        var isEnabled = String((enabledSelect && enabledSelect.value) || '0') === '1';
        try {
          await updateFeatureFlag(publicId, isEnabled);
          notify(tp('admin_ai.ai_feature_updated', 'AI feature updated'));
          await renderAdminAiPage();
        } catch (error) {
          var envelopeError = error && error.envelope ? error.envelope : null;
          notify((envelopeError && envelopeError.message) || tp('admin_ai.ai_feature_update_fail', 'Failed to update AI feature'), 'error');
        }
      });
      aiFlagsBody.dataset.bound = '1';
    }

    var intentsReloadBtn = document.getElementById('adminAiIntentsReloadBtn');
    if (intentsReloadBtn && intentsReloadBtn.dataset.bound !== '1') {
      intentsReloadBtn.addEventListener('click', function () {
        renderAdminAiPage();
      });
      intentsReloadBtn.dataset.bound = '1';
    }

    var usageReloadBtn = document.getElementById('adminAiUsageReloadBtn');
    if (usageReloadBtn && usageReloadBtn.dataset.bound !== '1') {
      usageReloadBtn.addEventListener('click', function () {
        renderAdminAiPage();
      });
      usageReloadBtn.dataset.bound = '1';
    }
    var usageRangeSelect = document.getElementById('adminAiUsageRange');
    if (usageRangeSelect) {
      usageRangeSelect.value = String(usageRangeDays);
      if (usageRangeSelect.dataset.bound !== '1') {
        usageRangeSelect.addEventListener('change', function () {
          var nextRange = Number(usageRangeSelect.value || 7);
          if (nextRange !== 1 && nextRange !== 7 && nextRange !== 30) nextRange = 7;
          window.CRM.__adminAiState = window.CRM.__adminAiState || {};
          window.CRM.__adminAiState.usageRangeDays = nextRange;
          renderAdminAiPage();
        });
        usageRangeSelect.dataset.bound = '1';
      }
    }

    var auditReloadBtn = document.getElementById('adminAiAuditReloadBtn');
    if (auditReloadBtn && auditReloadBtn.dataset.bound !== '1') {
      auditReloadBtn.addEventListener('click', function () {
        renderAdminAiPage();
      });
      auditReloadBtn.dataset.bound = '1';
    }

    if (intentsBody && intentsBody.dataset.bound !== '1') {
      intentsBody.addEventListener('click', async function (event) {
        var saveBtn = event.target.closest('[data-ai-intent-save]');
        if (!saveBtn) return;
        var intentCode = String(saveBtn.getAttribute('data-ai-intent-save') || '').trim();
        if (!intentCode) return;

        var featureFlagInput = intentsBody.querySelector('[data-ai-intent-feature-flag="' + intentCode.replace(/"/g, '\\"') + '"]');
        var modelInput = intentsBody.querySelector('[data-ai-intent-model="' + intentCode.replace(/"/g, '\\"') + '"]');
        var maxTokensInput = intentsBody.querySelector('[data-ai-intent-max-tokens="' + intentCode.replace(/"/g, '\\"') + '"]');
        var enabledSelect = intentsBody.querySelector('[data-ai-intent-enabled="' + intentCode.replace(/"/g, '\\"') + '"]');
        var sensitiveSelect = intentsBody.querySelector('[data-ai-intent-sensitive="' + intentCode.replace(/"/g, '\\"') + '"]');

        var payload = {
          feature_flag: String((featureFlagInput && featureFlagInput.value) || '').trim(),
          model: String((modelInput && modelInput.value) || '').trim(),
          max_tokens: Number((maxTokensInput && maxTokensInput.value) || 2000),
          is_enabled: String((enabledSelect && enabledSelect.value) || '1') === '1',
          allow_sensitive_context: String((sensitiveSelect && sensitiveSelect.value) || '0') === '1'
        };

        if (!Number.isFinite(payload.max_tokens) || payload.max_tokens <= 0) {
          notify(tp('admin_ai.valid_max_tokens_required', 'Enter a valid max_tokens value'), 'warning');
          return;
        }
        if (payload.is_enabled) {
          var hasActiveProvider = providers.some(function (item) { return Boolean(item && item.is_active); });
          var hasActivePrompt = promptTemplates.some(function (item) {
            return String(item && item.intent_code ? item.intent_code : '').trim() === intentCode
              && Boolean(item && item.is_active);
          });
          var hasActiveSchema = jsonSchemas.some(function (item) {
            return String(item && item.intent_code ? item.intent_code : '').trim() === intentCode
              && Boolean(item && item.is_active);
          });
          if (!hasActiveProvider || !hasActivePrompt || !hasActiveSchema) {
          notify(tp('admin_ai.intent_enable_requirements', 'Cannot enable an intent without an active connection, prompt and response format.'), 'warning');
            return;
          }
        }

        try {
          await request('api/v1/ai/intent-settings/' + encodeURIComponent(intentCode), {
            method: 'PATCH',
            headers: { 'X-Idempotency-Key': window.CRM.api.createIdempotencyKey('ai-intent-update') },
            body: payload
          });
          notify(tp('admin_ai.intent_updated', 'Intent updated'));
          await renderAdminAiPage();
        } catch (error) {
          var envelopeError = error && error.envelope ? error.envelope : null;
          notify((envelopeError && envelopeError.message) || tp('admin_ai.intent_update_fail', 'Failed to update intent'), 'error');
        }
      });
      intentsBody.dataset.bound = '1';
    }

    var promptsBody = document.getElementById('adminAiPromptsBody');
